After reading somewhere that you (Hadley) wished you could have designed ggplot2 using the magrittr pipe instead of the plus sign, I wondered whether it was possible to add support for the pipe without breaking old code. After a good bit of tinkering, I came up with a solution that seems to work pretty well.

```R
library(ggplot2)
library(dplyr)
library(magrittr)
library(lazyeval)
library(assertthat)

pipify_gg <- function(ggfun) {
    function(gg, ...) {
        dots <- list(...)
        if (missing(gg)) {
            return(do.call(ggfun, dots))
        } else if (is(gg, "gg")) {
            return(gg + do.call(ggfun, dots))
        } else {
            dots <- c(list(gg), dots)
            return(do.call(ggfun, dots))
        }
    }
}

## Standard evaluation functions just need to be wrapped in this
## function.
p_aes_string <- pipify_gg(aes_string)
p_geom_point <- pipify_gg(geom_point)
p_geom_smooth <- pipify_gg(geom_smooth)

## NSE functions need something fancier. (Are there any other NSE
## functions in ggplot2 besides aes?)
p_aes <- function(...) {
    dots <- lazy_dots(...)
    first_unnamed <- match("", names(dots))
    gg_evaled <- NULL
    if (!is.na(first_unnamed)) {
        gg_evaled <- try(lazy_eval(dots[[first_unnamed]]), silent=TRUE)
    }
    if (is(gg_evaled, "gg")) {
        dots[[first_unnamed]] <- NULL
    }
    aes <- dots %>% lapply(. %$% expr %>% deparse) %>% do.call(what=aes_string)
    aes <- ggplot2:::rename_aes(aes)
    if (is(gg_evaled, "gg")) {
        return(gg_evaled + aes)
    } else {
        return(aes)
    }
}

## Make this a function to get a new random set of points for each
## plot. This makes it easier to see that each invocation of ggplot is
## actually creating and printing a new plot.
mydata <- function () data_frame(x=rnorm(50), y=x+rnorm(50, sd=0.2))

## Now let's test it out

## Regular ggplot2
ggplot(mydata()) +
    aes(x=x, y=y) +
    geom_point() +
    geom_smooth()

## Pipified versions still work as drop-in replacements for the normal
## ones
ggplot(mydata()) +
    p_aes(x=x, y=y) +
    p_geom_point() +
    p_geom_smooth()

## But you can replace "+" with "%>%" and they still work
ggplot(mydata()) %>%
    p_aes(x=x, y=y) %>%
    p_geom_point() %>%
    p_geom_smooth()
